import{_ as t,C as r,o,c as i,E as n,a2 as l}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"恢复证据，不是重放授权","description":"","frontmatter":{"title":"恢复证据，不是重放授权","date":"2026-09-04","column":"open-source-engineering","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"当认证或人工批准中断工具调用时，智能体运行时应如何保存恢复证据，同时阻止在外部影响仍不确定时静默重放？","summary":"两个开源智能体项目在不同中断边界阻止工具调用被自动重放。共同教训是：恢复证据、继续执行的权限与外部影响证据必须分开保存；认证或批准成功，并不自动证明重放安全。","sources":["research/analysis/Q-20260904-03-recovery-evidence-replay-authority.md"],"item_id":"Q-20260904-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-04-recovery-evidence-is-not-replay-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-09-04-recovery-evidence-is-not-replay-authority.md","filePath":"zh/engineering/2026-09-04-recovery-evidence-is-not-replay-authority.md","lastUpdated":1788523639000}'),p={name:"zh/engineering/2026-09-04-recovery-evidence-is-not-replay-authority.md"};function s(c,e,d,h,u,m){const a=r("ArticleCover");return o(),i("div",null,[n(a,{image:"/assets/covers/daily-2026-09-04-recovery-evidence-is-not-replay-authority-cover.png",kicker:"开源工程 · 每日研究",title:"恢复证据，不是重放授权",summary:"两个开源智能体项目在不同中断边界阻止工具调用被自动重放。共同教训是：恢复证据、继续执行的权限与外部影响证据必须分开保存；认证或批准成功，并不自动证明重放安全。",version:"Q-20260904-03",status:"Daily Runtime V5 · 2026-09-04",languageHref:"/en/engineering/2026-09-04-recovery-evidence-is-not-replay-authority",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="恢复证据-不是重放授权" tabindex="-1">恢复证据，不是重放授权 <a class="header-anchor" href="#恢复证据-不是重放授权" aria-label="Permalink to &quot;恢复证据，不是重放授权&quot;">​</a></h1><p>一个工具调用因认证失败而中断。系统保存了认证挑战，用户随后也完成了登录。此时，运行时已经知道“怎样恢复”，也重新获得了“继续执行”的权限；但它仍可能不知道第一次请求是否已经在远端产生影响。如果把前两项事实直接等同于“可以安全重放”，一次看似成功的恢复就可能重复发消息、创建资源或提交付款。</p><p>这不是罕见的边缘问题。OpenAI Codex（OpenAI 开源编程智能体）与 Google ADK（谷歌智能体开发工具包）的两项维护者修复，在不同中断点阻止了同一类危险：当前执行路径不能因为获得恢复信息，便自行制造下一次有外部影响的尝试。</p><p>本文的判断是：<strong>被中断的工具调用应把恢复证据、继续执行的权限与外部影响证据作为三个独立状态维度保存。后续认证或批准可以恢复权限，却不能在前一次影响仍不确定时静默授权重放。</strong></p><h2 id="两项修复守住了不同的中断边界" tabindex="-1">两项修复守住了不同的中断边界 <a class="header-anchor" href="#两项修复守住了不同的中断边界" aria-label="Permalink to &quot;两项修复守住了不同的中断边界&quot;">​</a></h2><p>第一项修复位于 MCP（模型上下文协议）的认证恢复路径。该编程智能体项目在有限的 OAuth（开放授权协议）静默恢复失败后，保留一个或多个 万维网认证挑战信息信息，并把这次中断转换为携带认证元数据的失败工具调用结果。该分支不会自动重新发出被拒绝的调用；相应集成测试还观察事件流，并把这一调用限制为一次。</p><p>第二项修复位于人工确认路径。谷歌智能体开发工具包 在工具需要确认时设置 跳过摘要标记，防止暂停结果被送回模型循环后再次诱发工具调用。目标测试覆盖固定确认策略与可调用确认策略。</p><p>两项实现并不等价。该编程智能体项目 处理的是有限认证恢复已经失败后的边界；谷歌智能体开发工具包 处理的是人工确认尚未完成时的暂停边界。它们共同支持的，只是一个较窄但可复用的约束：中断信息可以保留，当前执行路径的自主重放能力必须停止。</p><h2 id="知道如何恢复-不等于有权执行" tabindex="-1">知道如何恢复，不等于有权执行 <a class="header-anchor" href="#知道如何恢复-不等于有权执行" aria-label="Permalink to &quot;知道如何恢复，不等于有权执行&quot;">​</a></h2><p>恢复证据回答的是“为什么停下”和“下一步需要什么”。认证挑战指出需要新的凭据或交互；确认请求指出需要人的决定。这些信息对恢复很重要，却不包含授权决定本身。</p><p>如果运行时把认证挑战、确认表单或错误对象当成隐含权限，控制边界便会被诊断数据改写。更稳健的模型会把调用放入“携带证据的中断状态”：保留稳定的调用发生身份、输入摘要、恢复要求和当前暂停原因，但明确撤销这一执行路径继续产生外部影响的能力。</p><p>后续事件应当单独改变权限状态。用户完成认证、批准特定参数，或新的调度机会获得准入，都可能让系统重新具备执行资格；它们不是第一次尝试安全重放的证明。</p><h2 id="重新取得权限-仍未回答第一次调用发生了什么" tabindex="-1">重新取得权限，仍未回答第一次调用发生了什么 <a class="header-anchor" href="#重新取得权限-仍未回答第一次调用发生了什么" aria-label="Permalink to &quot;重新取得权限，仍未回答第一次调用发生了什么&quot;">​</a></h2><p>认证成功能证明当前凭据可用，人工批准能证明某个主体接受了某个范围内的操作。二者都不自动说明远端在中断前是否已经提交副作用。</p><p>某些协议可以证明请求在业务执行前被拒绝；某些工具天然幂等；还有一些系统提供稳定请求键与可查询回执。在这些条件下，重试可能合理。反之，如果客户端只看到超时、连接断开或模糊错误，外部影响就可能处于“不确定”状态。</p><p>因此，重放准入至少要同时检查两件事：当前是否有权执行，以及前一次影响是否已经被证明未发生、可安全去重、能够对账或可以补偿。缺少第二项时，系统应查询外部状态、要求人工接受不确定性，或进入补偿流程，而不是把新权限直接转换为新调用。</p><h2 id="三类证据需要同一发生身份-但不能合并" tabindex="-1">三类证据需要同一发生身份，但不能合并 <a class="header-anchor" href="#三类证据需要同一发生身份-但不能合并" aria-label="Permalink to &quot;三类证据需要同一发生身份，但不能合并&quot;">​</a></h2><p>一个受治理的运行时可以围绕稳定的工具调用发生身份，分别记录三类状态：</p><ol><li>恢复证据：认证挑战、确认请求、失败位置以及继续恢复所需条件。</li><li>执行权限：当前主体、适用策略、批准范围、凭据状态与有效期。</li><li>影响证据：请求是否未发出、已拒绝、已提交、结果未知、已对账或已补偿。</li></ol><p>三者共享同一发生身份，便于审计与关联；三者又必须独立变化，避免错误推断。新的批准可能更新权限，但不改变旧影响；新的远端回执可能澄清影响，却不延长已经失效的批准。</p><p>恢复后的继续执行还应拥有新的执行轮次，并保留与原发生、恢复事件和准入决定的关系。这样既能追踪连续工作，也不会把两次尝试压成一条无法解释的历史。</p><h2 id="安全边界不应变成无条件阻断" tabindex="-1">安全边界不应变成无条件阻断 <a class="header-anchor" href="#安全边界不应变成无条件阻断" aria-label="Permalink to &quot;安全边界不应变成无条件阻断&quot;">​</a></h2><p>禁止自动重放会降低活性。对无副作用的查询、明确幂等的写入，或能证明业务执行前已拒绝的请求，反复要求人工介入并无必要。</p><p>关键不是“所有失败都禁止重试”，而是“重试理由必须来自显式合同”。工具描述可以声明重放安全；调用可以带稳定幂等键；外部系统可以提供影响查询；策略也可以对低风险操作允许有限自动重试。运行时需要记录使用了哪一种依据，而不能只记录“上次报错”。</p><p>测试同样应覆盖负面路径：恢复元数据出现后，模型不得自行再次调用；确认暂停不得回到模型循环；认证完成后，如果影响仍未知，系统不得绕过对账；参数、凭据或目标状态变化时，旧批准必须重新评估。</p><h2 id="证据边界与开放问题" tabindex="-1">证据边界与开放问题 <a class="header-anchor" href="#证据边界与开放问题" aria-label="Permalink to &quot;证据边界与开放问题&quot;">​</a></h2><p>这里的公开一手事实来自两个项目自己的维护者提交与测试，因此能说明相应版本中的控制流变化，但不是独立生产验证。本文提出的三维状态模型是基于两项实现的研究解释，尚未得到跨系统实验验证。</p><p>现有证据也不能证明恰好一次外部影响、分布式去重、批准者身份或批准范围，更不能证明远端在客户端观察到失败前绝未提交。把结论限制在“阻止当前路径自主重放”，比宣称完整的事务安全更准确。</p><p>仍待回答的问题包括：哪些工具协议能证明业务执行前拒绝；外部影响回执应如何绑定一次调用；参数、凭据和目标状态变化到何种程度会使批准失效；以及系统应如何表达影响不确定而不造成永久停滞。</p><p>恢复证据告诉运行时如何继续。重放授权还必须回答另一个问题：继续执行会不会重复现实世界中已经发生、却尚未被本地确认的动作。</p><p><strong>一手来源：</strong></p><ul><li><a href="https://github.com/openai/codex/commit/0650d6d1ca451b67009b3969a82b87e76979975f" target="_blank" rel="noreferrer">编程智能体项目 维护者提交：保留认证挑战并停止自动重放</a></li><li><a href="https://github.com/google/adk-python/commit/cb0eb2288bfe6536bd6e98f0601d3736844062ca" target="_blank" rel="noreferrer">谷歌智能体开发工具包 维护者提交：阻止确认暂停重新进入模型循环</a></li></ul>',32))])}const g=t(p,[["render",s]]);export{_ as __pageData,g as default};
